/bin/bash -lc 'tmp_verify_dir=$(mktemp -d "${TMPDIR%/}/dmc-saxena.XXXXXX")
for q in '"'\"Dr. M. C. Saxena College of Pharmacy\" Lucknow' '\"M C Saxena\" pharmacy Lucknow official' 'site:edu.in \"Saxena\" \"College of Pharmacy\" Lucknow' '\"Dr. M.C. Saxena College of Pharmacy\"'; do
  echo \"QUERY: "'$q"
  curl --insecure --silent --show-error --fail --location --max-time 30 -A '"'Mozilla/5.0' --get --data-urlencode \"q="'$q" '"'https://www.bing.com/search' | python3 -c 'import sys,re,html; s=sys.stdin.read();
for m in re.finditer(r\"<li class=\\\\\"b_algo\\\\\".*?</li>\",s,re.S):
 x=m.group(0); a=re.search(r\"<h2>.*?<a href=\\\\\"(["'^'"\\\\\"]+)\\\\\"["'^>]*>(.*?)</a>",x,re.S); p=re.search(r"<p>(.*?)</p>",x,re.S)
 if a:
  clean=lambda z: re.sub(r"<[''^>]+>"," ",html.unescape(z)); print(clean(a.group(2)).strip()+" | "+a.group(1)+" | "+(clean(p.group(1)).strip() if p else ""))'"'
done
rm -rf \""'$tmp_verify_dir"'

